<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $user = App\Models\User::first(); $req = Illuminate\Http\Request::create('/api/v1/dashboard/summary', 'GET'); $req->setUserResolver(fn() => $user); $res = app(\App\Http\Controllers\DashboardController::class)->index($req); echo json_encode($res->getData(), JSON_PRETTY_PRINT);
